            variant.starts_with(|c: char| c.is_ascii_alphabetic()),
            "invalid icon name: {stem}"
        );
        assert!(
            variant.chars().all(|c| c.is_ascii_alphanumeric()),
            "invalid icon name: {stem}"
        );
        assert!(
            icons.insert(variant, format!("icons/{stem}.svg")).is_none(),
            "duplicate icon variant: {stem}"
        );
